            }


        } catch (DataAccessException e) {
            logger.fatal(e.getMessage());

            throw e;
        }
        if (logger.isDebugEnabled()) {
            logger.debug(" CodeListApplicationServiceImpl : batchCodeProcess 종료 ");
        }
    }


