void Set::Generator(int len,  char* arr)
{
	char *uni = new char[N + 1];
	uni[N] = 0;
	for (int i = 0; i < N; i++)
	{
		uni[i] = '' + i;
	}

	for (int i = 0; i < len; i++)
	{
		int p = rand() % (N - i);
		if (p)
		{
			std::swap(uni[p + i], uni[i]);
		}
	}

	for (int i = 0; i < len; i++)
	{
		arr[i] = uni[i];
	}
	arr[len] = 0;

	delete[] uni;
}
