    protected void setStatusBar() {
        StatusBarUtil.setStatusBarColor(this, AppContext.mResource.getColor(R.color.app_color_blue));
    }

    @Override
    public void setView() {
        setContentView(R.layout.activity_notice_detail);
    }

    @Override
    public void setListener() {

    }
