class Solution:
    """
    @param: matrix: matrix, a list of lists of integers
    @param: target: An integer
    @return: a boolean, indicate whether matrix contains target
    """
    def searchMatrix(self, matrix, target):
        if matrix == None:
            return False
        if len(matrix) == 0:
            return False
        if len(matrix[0]) == 0:
            return False

        # write your code here
        lown = 0
        hein = len(matrix) - 1
        halfn = int((lown + hein)/2)
        n = 0

        lowm = 0
        heim = len(matrix[0]) - 1
        lenm = len(matrix[0]) - 1
        halfm = int((lowm + heim)/2)
        while lown <= hein:
            if matrix[halfn][lenm] < target :
                lown = halfn + 1
            elif  matrix[halfn][0] > target:
                hein = halfn - 1
            elif matrix[halfn][0] < target and matrix[halfn][lenm] > target:
                n = halfn
                break
            else:
                return True
            halfn = int((lown + hein)/2)
            print(halfn)
        while lowm <= heim :
            if matrix[n][halfm] < target:
                lowm = halfm + 1
            elif  matrix[n][halfm] > target :
                heim = halfm - 1
            else:
                return True
            halfm = int((lowm + heim)/2)
        return False

