> * `Solution 5`:
```javascript
    function maxSubArray(array) {
        let temp = 0;
        let max = 0;
        let allNegative = true;
        array.forEach(val => {
            if (val >= 0) {
                allNegative = false;
            };
            temp = Math.max(0, temp + val);
            max = Math.max(max, temp)
        });
        if (allNegative) {
            return Math.max(...array);
        };
        return max;
    };
```

