    return true;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (b[p][i][j] != b[q][i][j]) return false;
    return false;
}
void rotate(int p, int q)
{
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            b[q][n-j-1][i] = b[p][i][j];
    int v = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            v = (v*2 + b[q][i][j]) % MOD;
    h[q] = v;
}
