    }*/
    for(element = 0; element<6;element++)
    {
        value = 0;
        for(byte = 1;byte<=4;byte++)
        {
            int num = getchar();
            unsigned char part = num & 0xff;
            if(num==EOF) return 0;
            value = value + part;
            if(byte!=4)
                value = value <<8 ;

        }

       /* if(element == 0)
