        int value = 0;
        for(byte = 0;byte<bytes_per_sample;byte++)
        {

            if(byte == 0)
            {

                //char c = getchar();
                int m = getchar();
                char c =   m & 0xff;
                if(m==EOF)
                {
                   // printf("error in read frame most sig");
                    return 0;
                }
                value = value+c;

            }
            else
            {
                //unsigned char c = getchar();
                int m = getchar();
                unsigned char c =   m & 0xff;
                if(m==EOF)
                {
                        //printf("error in read frame");
                        return 0;
                }
                value = value<<8;
            // printf("val:%d",value);
                value = value+c;
            }
           /* if(c==EOF)
            {
                printf("eof");
                return 0;
            }*/

            //printf("char:%c",c);

