function toJSON() {
  var self = this;

  var result = {}
  Object.keys(self).forEach(function(key) {
    var val = self[key]

    if(key == 'toJSON')
      return
    else if(key == 'this')
      result[key] = "" + val
    else if(typeof val == 'function')
      result[key] = "" + val
    else
      result[key] = self[key]
  })

  return result
}
